trial.program_source:
def transform(grid):
    out=[row[:] for row in grid]
    for color in sorted({v for row in grid for v in row if v}):
        pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
        if pts and all(c>r for r,c in pts):
            for r,c in pts: out[r][c]=5
            break
    return out

